import Foundation
import AVFoundation
import CoreVideo
import ImageIO
import CoreServices
import XCTest

final class NativePreparationTests:XCTestCase {
 var paths:[String]=[]
 override func tearDown() {for p in paths {try? FileManager.default.removeItem(atPath:p)}}
 func video() throws ->String {let export=try AvatarVideoExport(codec:AVVideoCodecType.h264.rawValue);var pixel:CVPixelBuffer?;XCTAssertEqual(CVPixelBufferCreate(kCFAllocatorDefault,640,640,kCVPixelFormatType_32ARGB,nil,&pixel),kCVReturnSuccess);let buffer=try XCTUnwrap(pixel);CVPixelBufferLockBaseAddress(buffer,[]);if let bytes=CVPixelBufferGetBaseAddress(buffer) {memset(bytes,0,CVPixelBufferGetDataSize(buffer))};CVPixelBufferUnlockBaseAddress(buffer,[]);let done=expectation(description:"Fixture video");let queue=DispatchQueue(label:"avatar-video-source");var index=0;var path:String?;queue.async {export.start(queue:queue,isCancelled:{false},next:{if index==3 {return .finished(CMTime(value:3,timescale:24))};defer {index+=1};return .frame(buffer,CMTime(value:Int64(index),timescale:24))},completed:{path=$0;done.fulfill()})};wait(for:[done],timeout:20);let output=try XCTUnwrap(path);paths.append(output);return output}
 func prepared(_ path:String) throws ->AvatarPreparedVideo {switch AvatarPreparedVideo.prepare(path:path) {case let .success(value):return value;case .failure:throw NSError(domain:"Preparation failed",code:1)}}
 func testRealVideoCopyAndJpegThumbnailAreReadable() throws {let input=try video();let result=try prepared(input);XCTAssertNotEqual(result.videoPath,input);XCTAssertFalse(result.thumbnailPath.isEmpty);let source=try XCTUnwrap(CGImageSourceCreateWithURL(URL(fileURLWithPath:result.thumbnailPath) as CFURL,nil));XCTAssertEqual(CGImageSourceGetType(source),kUTTypeJPEG);let thumbnail=try XCTUnwrap(CGImageSourceCreateImageAtIndex(source,0,nil));XCTAssertEqual(thumbnail.width,640);XCTAssertEqual(thumbnail.height,640);let asset=AVURLAsset(url:URL(fileURLWithPath:result.videoPath));XCTAssertEqual(asset.tracks(withMediaType:.video).count,1);XCTAssertEqual(asset.duration.seconds,0.125,accuracy:0.02);XCTAssertEqual(try Data(contentsOf:URL(fileURLWithPath:input)),try Data(contentsOf:URL(fileURLWithPath:result.videoPath)))}
 func testUnclaimedPreparedFilesAreRemovedOnRelease() throws {let input=try video();var result:AvatarPreparedVideo?=try prepared(input);let video=result!.videoPath,thumb=result!.thumbnailPath;result=nil;XCTAssertFalse(FileManager.default.fileExists(atPath:video));XCTAssertFalse(FileManager.default.fileExists(atPath:thumb));XCTAssertTrue(FileManager.default.fileExists(atPath:input))}
 func testTransferredFilesSurviveOwnerRelease() throws {let input=try video();var result:AvatarPreparedVideo?=try prepared(input);let files=result!.takeFiles();paths.append(contentsOf:[files.video,files.thumbnail]);result=nil;XCTAssertTrue(FileManager.default.fileExists(atPath:files.video));XCTAssertTrue(FileManager.default.fileExists(atPath:files.thumbnail))}
 func testMissingSourceIsFailure() {if case .success=AvatarPreparedVideo.prepare(path:"/nonexistent/avatar-video") {XCTFail("Missing source must fail")}}
 func testInvalidVideoDataIsFailureAndOriginalSurvives() throws {let p=NSTemporaryDirectory()+UUID().uuidString;paths.append(p);try Data([1,2,3]).write(to:URL(fileURLWithPath:p));if case .success=AvatarPreparedVideo.prepare(path:p) {XCTFail("Invalid video must fail")};XCTAssertEqual(try Data(contentsOf:URL(fileURLWithPath:p)),Data([1,2,3]))}
 func testDirectorySourceIsFailureAndOriginalSurvives() throws {let p=NSTemporaryDirectory()+UUID().uuidString;paths.append(p);try FileManager.default.createDirectory(atPath:p,withIntermediateDirectories:false);if case .success=AvatarPreparedVideo.prepare(path:p) {XCTFail("Directory must fail")};XCTAssertTrue(FileManager.default.fileExists(atPath:p))}
}
